#include <cstdio>
using namespace std;
struct node{
	int to;
	node *next;
};
int i,j,m,n,a[1000005],f[1000005],dp[1000005],deg[1000005],k;
node *nd[1000005];
void addd(int u,int v){
	node *p=new node();
	p->to=v;
	p->next=nd[u];
	nd[u]=p;
}
void dfs(int u){
	node *p=nd[u];
	if ((u>1)&&(deg[u]==1)){//note that u>1
		dp[u]=1;
		k++;
		return;
	}
	if (a[u]) dp[u]=1000000000;
	else dp[u]=0;
	while(p){
		dfs(p->to);
		if (a[u]){
			if (dp[p->to]<dp[u]) dp[u]=dp[p->to];
		}else{
			dp[u]+=dp[p->to];
		}
		p=p->next;
	}
}
int main(){
	scanf("%d",&n);
	for(i=1;i<=n;i++){
		scanf("%d",&a[i]);
	}
	for(i=2;i<=n;i++){
		scanf("%d",&f[i]);
		deg[i]++;
		deg[f[i]]++;
		addd(f[i],i);
	}
	dfs(1);
	printf("%d\n",k+1-dp[1]);
	return 0;
}

#include <cstdio>
using namespace std;
const int N=1000005;
int n,p;
int h[N],nx[N];
int t[N],sz[N];
void getsize(int u)
{
	if (!h[u])
		sz[u]++;
	for (int i=h[u];i;i=nx[i])
	{
		getsize(i);
		sz[u]+=sz[i];
	}
}
int getans(int u)
{
	if (!h[u])
		return 1;
	int ret=0,tmp;
	if (t[u])
	{
		for (int i=h[u];i;i=nx[i])
		{
			tmp=getans(i)+sz[u]-sz[i];
			if (tmp>ret)
				ret=tmp;
		}
		return ret;
	}
	for (int i=h[u];i;i=nx[i])
		ret+=getans(i)-1;
	return ret+1;
}
int main()
{
	scanf("%d",&n);
	for (int i=1;i<=n;i++)
		scanf("%d",&t[i]);
	for (int i=2;i<=n;i++)
	{
		scanf("%d",&p);
		nx[i]=h[p];
		h[p]=i;
	}
	getsize(1);
	printf("%d\n",getans(1));
	return 0;
}

#include <cstdio>
using namespace std;
const int mod=998244353;
const int N=4005;
const int K=2005;
int n,k,l;
int fac,ans;
int f[N][K][2];
int fpw(int b,int e=mod-2)
{
	if (!e)
		return 1;
	int ret=fpw(b,e>>1);
	ret=1ll*ret*ret%mod;
	if (e&1)
		ret=1ll*ret*b%mod;
	return ret;
}
int main()
{
	scanf("%d%d%d",&n,&k,&l);
	f[0][0][0]=1;
	for (int i=1;i<=2*n+1;i++)
		for (int j=0;j<=n;j++)
			for (int x=0;x<=1;x++)
				if (f[i-1][j][x])
				{
					if (j)
						f[i][j-1][x]=(f[i][j-1][x]+1ll*f[i-1][j][x]*j)%mod;
					if (i+j-1<2*n+x)
						f[i][j+1][x]=(f[i][j+1][x]+f[i-1][j][x])%mod;
					if (j>=k&&!x)
						f[i][j][1]=(f[i][j][1]+f[i-1][j][x])%mod;
				}
	fac=1;
	for (int i=n+1;i<=2*n+1;i++)
		fac=1ll*fac*i%mod;
	ans=f[2*n+1][0][1];
	ans=1ll*ans*fpw(2,n)%mod;
	ans=1ll*ans*fpw(fac)%mod*l%mod;
	printf("%d\n",ans);
	return 0;
}
